  ('Tamarac River', 'Creek', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-96.57715195206379, 48.48185020311746), 4326)::extensions.geography),
  ('Roseau River', 'Creek', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-96.40547973070584, 48.979857477152805), 4326)::extensions.geography),
  ('Red Lake River', 'Creek', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-96.07959193836216, 48.080298794898376), 4326)::extensions.geography),
  ('Middle River', 'Creek', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-96.85943760933782, 48.35723556472294), 4326)::extensions.geography),
